mapper.select:
select o.id , o.order_no as orderNo,o.merchant_id as merchantId,m.name as merchantName, o.pay_amount as payAmount,o.status,o.create_time as createTime,o.source from `order` o left join merchant_profile m on o.merchant_id = m.user_id
and order_no like concat('%', #{dto.keyword}, '%')
and status = #{dto.status}
and o.source = #{dto.source}
and deleted = 0 order by m.create_time desc

select o.id,o.order_no as orderNo,o.pay_amount as payAmount,o.status,o.create_time as createTime,
       u.nickname as buyerName,o.source
from `order` o
left join user_profile u on o.user_id = u.user_id


    and order_no like concat('%', #{dto.keyword}, '%')


    and status = #{dto.status}


    and o.source = #{dto.source}

and deleted = 0 and o.merchant_id = #{merchantId}
order by o.create_time desc

select o.id,o.order_no as orderNo,o.pay_amount as payAmount,o.status,o.create_time as createTime, u.nickname as buyerName,m.shop_name as merchantName,o.receiver_name as receiverName, o.receiver_address as receiverAddress,o.receiver_phone as receiverPhone,o.pay_time as payTime,o.source from `order` o left join merchant_profile m on m.user_id = o.merchant_id left join user_profile u on o.user_id = u.user_id
and order_no like concat('%', #{dto.keyword}, '%')
and status = #{dto.status}
and o.source = #{source}
and o.deleted = 0 order by m.create_time desc
